import numpy as np

def binary_cross_entropy(y_true, y_pred, epsilon=1e-12):
    y_pred_clipped = np.clip(y_pred, epsilon, 1 - epsilon)  # the numerical stability fix covered in this topic
    return -np.mean(y_true * np.log(y_pred_clipped) + (1 - y_true) * np.log(1 - y_pred_clipped))

def mse(y_true, y_pred):
    return np.mean((y_true - y_pred) ** 2)

y_true = np.array([1])

print("True label = 1")
print("Prediction | Binary Cross Entropy | MSE")
for prediction in [0.99, 0.9, 0.5, 0.1, 0.01]:
    y_pred = np.array([prediction])
    bce = binary_cross_entropy(y_true, y_pred)
    mse_value = mse(y_true, y_pred)
    print(f"   {prediction:.2f}    |        {bce:.4f}        | {mse_value:.4f}")

print("\nNotice Binary Cross Entropy escalates dramatically as the prediction moves from confidently correct (0.99)")
print("to confidently wrong (0.01), while MSE's penalty grows far more gently by comparison")
